import mq3.client.ui_specifyleague as s
import mq3.client.ui_qmenu as q
function req(ok,label) if not ok then return error(7996,"specifyleague: "+label) end if;return 1 end function
function leagues() return ["Alpha League","Beta League","Gamma League"] end function
function main(args) count=0;v=s.create(false);s.SpecifyLeague_MenuInit(v,"Player",leagues());count=count+req(len(v.menu.items)==10 and v.banner.string=="CHOOSE LEAGUE","menu layout");count=count+req(len(v.actions)==10 and v.actions[9].kind=="get-leagues","cache plus query");count=count+req(v.list.numitems==3 and v.displayNames==leagues() and v.playername=="Player","league list");s.SpecifyLeague_Event(v,s.ID_SPECIFYLEAGUEDOWN,q.QM_ACTIVATED,leagues());count=count+req(v.list.curvalue==1,"down selection");s.SpecifyLeague_Event(v,s.ID_SPECIFYLEAGUEUP,q.QM_ACTIVATED,leagues());count=count+req(v.list.curvalue==0,"up selection");before=len(v.actions);v.rankname.buffer="Play";count=count+req(not s.SpecifyLeague_Event(v,s.ID_SPECIFYLEAGUENAME,q.QM_LOSTFOCUS,leagues()) and len(v.actions)==before,"prefix change preserves original filter");v.rankname.buffer="Other";count=count+req(s.SpecifyLeague_Event(v,s.ID_SPECIFYLEAGUENAME,q.QM_LOSTFOCUS,["Other League"]) and v.list.numitems==1,"name change refresh");count=count+req(s.SpecifyLeague_Event(v,s.ID_SPECIFYLEAGUEBACK,q.QM_ACTIVATED,["Other League"]) and v.selected=="Other League" and v.popped,"select and back");count=count+req(v.actions[len(v.actions)-2].name=="sv_leagueName" and v.actions[len(v.actions)-2].text=="Other League","league cvar");long=[];for i=0 to 130 long=long+["League "+str(i)] end for;cap=s.create(false);s.SpecifyLeague_MenuInit(cap,"Player",long);count=count+req(cap.list.numitems==128,"list cap");empty=s.create(false);s.SpecifyLeague_MenuInit(empty,"Player",[]);count=count+req(s.SpecifyLeague_Event(empty,s.ID_SPECIFYLEAGUEBACK,q.QM_ACTIVATED,[]) and empty.popped,"empty list back safe");silent=s.create(true);s.UI_SpecifyLeagueMenu(silent,"Player",leagues());ok=true;for each a in silent.actions if a.dispatched then ok=false end if end for;count=count+req(silent.pushed and ok,"push and suppression");print("PASS: "+str(count)+" UI specifyleague contracts");return 0 end function
